//! Game world X/Z (metres) → WGS84 longitude/latitude (PLAN §8), so a route
//! lines up with basemap tiles generated by truckermudgeon/maps.
//!
//! Both games use a spherical Lambert conformal conic projection whose
//! parameters are in each game's `def/climate.sii`. The maths is the standard
//! one (Snyder, "Map Projections: A Working Manual", USGS 1987, §15), written
//! here from the formulas. The ETS2 UK correction (UK content is authored 0.75×
//! smaller, around Calais) follows truckermudgeon/maps, credited, not copied.

use crate::game::Game;

/// The sphere's radius cancels out (game metres are scaled by a length per
/// degree of the same sphere); Clarke 1866 authalic, as the basemap uses.
const EARTH_RADIUS_M: f64 = 6_370_997.0;

fn length_of_degree() -> f64 {
    EARTH_RADIUS_M * std::f64::consts::PI / 180.0
}

/// A spherical Lambert conformal conic with two standard parallels.
struct Lcc {
    n: f64,
    rf: f64,
    rho0: f64,
    lon0: f64,
}

fn t(lat: f64) -> f64 {
    (std::f64::consts::FRAC_PI_4 + lat / 2.0).tan()
}

impl Lcc {
    fn new(lat1: f64, lat2: f64, lat0: f64, lon0: f64) -> Lcc {
        let (p1, p2, p0) = (lat1.to_radians(), lat2.to_radians(), lat0.to_radians());
        let n = (p1.cos() / p2.cos()).ln() / (t(p2) / t(p1)).ln();
        let rf = EARTH_RADIUS_M * p1.cos() * t(p1).powf(n) / n;
        Lcc { n, rf, rho0: rf / t(p0).powf(n), lon0: lon0.to_radians() }
    }

    /// Projected metres → (lon, lat) in degrees.
    fn inverse(&self, x: f64, y: f64) -> [f64; 2] {
        let s = self.n.signum();
        let dy = self.rho0 - y;
        let rho = s * (x * x + dy * dy).sqrt();
        let theta = (s * x).atan2(s * dy);
        let lat = 2.0 * (self.rf / rho).powf(1.0 / self.n).atan() - std::f64::consts::FRAC_PI_2;
        [(self.lon0 + theta / self.n).to_degrees(), lat.to_degrees()]
    }

    /// (lon, lat) in degrees → projected metres.
    fn forward(&self, lon: f64, lat: f64) -> [f64; 2] {
        let rho = self.rf / t(lat.to_radians()).powf(self.n);
        let theta = self.n * (lon.to_radians() - self.lon0);
        [rho * theta.sin(), self.rho0 - rho * theta.cos()]
    }
}

/// One game's `def/climate.sii` projection.
struct Params {
    lat1: f64,
    lat2: f64,
    lat0: f64,
    lon0: f64,
    /// `map_factor`: [for Z, for X].
    factor: [f64; 2],
    /// `map_offset`, subtracted first (ETS2 only).
    offset: [f64; 2],
}

const ATS: Params = Params {
    lat1: 33.0,
    lat2: 45.0,
    lat0: 39.0,
    lon0: -96.0,
    factor: [-0.00017706234, 0.000176689948],
    offset: [0.0, 0.0],
};

const ETS2: Params = Params {
    lat1: 37.0,
    lat2: 65.0,
    lat0: 50.0,
    lon0: 15.0,
    factor: [-0.000171570875, 0.0001729241463],
    offset: [16660.0, 4150.0],
};

/// ETS2's UK: 4 km map sectors up and to the left of the one holding Calais.
const SECTOR_M: f64 = 4000.0;
const UK_SCALE: f64 = 0.75;
const CALAIS: [f64; 2] = [-31100.0, -5500.0];

fn in_uk(x: f64, z: f64) -> bool {
    let (sx, sz) = ((x / SECTOR_M).floor(), (z / SECTOR_M).floor());
    sx <= -8.0 && sz <= -2.0 && !(sx == -8.0 && sz == -2.0)
}

fn params(game: Game) -> &'static Params {
    match game {
        Game::Ats => &ATS,
        Game::Ets2 => &ETS2,
    }
}

fn lcc(p: &Params) -> Lcc {
    Lcc::new(p.lat1, p.lat2, p.lat0, p.lon0)
}

/// Game world X and Z (the SDK's `placement` x and z, metres) → `[lon, lat]`.
pub fn to_lon_lat(game: Game, x: f64, z: f64) -> [f64; 2] {
    let p = params(game);
    let (mut gx, mut gz) = (x - p.offset[0], z - p.offset[1]);
    if game == Game::Ets2 && in_uk(x, z) {
        gx = (gx + CALAIS[0] / 2.0) * UK_SCALE;
        gz = (gz + CALAIS[1] / 2.0) * UK_SCALE;
    }
    let deg = length_of_degree();
    lcc(p).inverse(gx * p.factor[1] * deg, gz * p.factor[0] * deg)
}

/// `[lon, lat]` → game world X and Z; the inverse of [`to_lon_lat`].
pub fn from_lon_lat(game: Game, lon: f64, lat: f64) -> [f64; 2] {
    let p = params(game);
    let deg = length_of_degree();
    let [px, py] = lcc(p).forward(lon, lat);
    let (mut gx, mut gz) = (px / p.factor[1] / deg, py / p.factor[0] / deg);
    if game == Game::Ets2 {
        let (ux, uz) = (gx / UK_SCALE - CALAIS[0] / 2.0, gz / UK_SCALE - CALAIS[1] / 2.0);
        if in_uk(ux + p.offset[0], uz + p.offset[1]) {
            (gx, gz) = (ux, uz);
        }
    }
    [gx + p.offset[0], gz + p.offset[1]]
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Reference points from truckermudgeon/maps' own tests, so routes line up
    /// with its tiles: (game, game X/Z, lon/lat).
    const POINTS: [(Game, [f64; 2], [f64; 2]); 4] = [
        (Game::Ats, [-85_672.0, 7870.0], [-114.92606131601985, 36.00959614633237]), // near Las Vegas
        (Game::Ets2, [-40_169.0, -10_685.0], [-0.5943602137854889, 51.29443960532431]), // south of London (UK)
        (Game::Ets2, [62_276.0, 84_880.0], [24.63877984644102, 35.391305791648065]), // Crete
        (Game::Ets2, [-30_120.0, 5_847.0], [2.2454398875049852, 48.96983557895307]), // Paris
    ];

    #[test]
    fn known_points() {
        for (game, xz, ll) in POINTS {
            let got = to_lon_lat(game, xz[0], xz[1]);
            assert!((got[0] - ll[0]).abs() < 1e-9 && (got[1] - ll[1]).abs() < 1e-9, "{game:?} {xz:?}: {got:?} != {ll:?}");
            let back = from_lon_lat(game, ll[0], ll[1]);
            assert!((back[0] - xz[0]).abs() < 1e-5 && (back[1] - xz[1]).abs() < 1e-5, "{game:?} {ll:?}: {back:?} != {xz:?}");
        }
    }

    #[test]
    fn uk_sectors() {
        assert!(in_uk(-40_169.0, -10_685.0));
        assert!(!in_uk(-30_120.0, 5_847.0));
        // The sector holding Calais itself is the continent.
        assert!(!in_uk(-31_100.0, -5_500.0));
        assert!(in_uk(-32_001.0, -5_500.0));
    }
}
